<?php
declare(strict_types=1);
require_once __DIR__.'/_bootstrap.php';
adminRequireLogin();
$db=\Kios\Infrastructure\Database::connect();
$q=$db->prepare('SELECT p.product_id,p.name,p.active,p.available,p.version,c.name category FROM products p JOIN outlets o ON o.outlet_id=p.outlet_id LEFT JOIN categories c ON c.category_id=p.category_id AND c.outlet_id=p.outlet_id WHERE o.outlet_code=? ORDER BY p.product_id');$q->execute([KIOS_ADMIN_OUTLET]);$products=$q->fetchAll(PDO::FETCH_ASSOC);$ids=array_column($products,null,'product_id');
$store=new \Kios\Infrastructure\CatalogueReviewStore(dirname(__DIR__,2).'/storage/owner-catalogue-review');
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){
 try{adminRequireCsrf();$id=adminPost('product_id');$version=adminPost('version');if(!ctype_digit($id)||!isset($ids[(int)$id])||!ctype_digit($version))throw new DomainException('Invalid product or version.');if(adminPost('action')==='availability'){if(!in_array(adminPost('available'),['0','1'],true))throw new DomainException('Invalid availability.');adminRepository()->setAvailability(KIOS_ADMIN_OUTLET,(int)$id,(int)$version,adminPost('available')==='1');}else{$store->save((int)$id,adminPost('decision'),adminPost('notes'),(int)$version);}adminFlash(adminPost('action')==='availability'?'Product availability saved. Routing approval is still required for ordering.':'Review decision saved. Ordering settings were not changed.');header('Location: /admin/catalogue-review.php?product_id='.(int)$id,true,303);exit;}
 catch(Throwable $e){http_response_code($e instanceof DomainException?400:500);$error=adminFail($e);}
}
$state=$store->read();
function csvSafe(string $s):string{return preg_match('/^[\s]*[=+@-]/u',$s)?"'".$s:$s;}
if(($_GET['export']??'')==='csv'){
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="kios-owner-product-decisions.csv"');$out=fopen('php://output','w');fputcsv($out,['Product ID','Name','Category','Decision','Notes','Version','Updated UTC']);foreach($products as $p){$d=$state['decisions'][(string)$p['product_id']]??['decision'=>'PENDING','notes'=>'','version'=>0,'updated_utc'=>''];fputcsv($out,[$p['product_id'],csvSafe($p['name']),csvSafe((string)$p['category']),$d['decision'],csvSafe($d['notes']),$d['version'],$d['updated_utc']]);}exit;
}
adminStart('Owner catalogue decisions');echo '<div class="owner-review"><p>All '.count($products).' product records. These decisions are proposals only; they never change ordering, prices, availability or routing.</p><p><a href="/catalogue-review.php">Inspect photographs</a> · <a href="?export=csv">Export all decisions CSV</a></p>';
if($error!=='')echo '<p role="alert">'.adminH($error).'</p>';
echo '<form method="get"><label>Product<select name="product_id">';foreach($products as $p)echo '<option value="'.adminH($p['product_id']).'"'.((string)$p['product_id']===($_GET['product_id']??'')?' selected':'').'>ID '.adminH($p['product_id']).' — '.adminH($p['name']).'</option>';echo '</select></label><button class="admin-button">Select product</button></form>';
$id=(int)($_GET['product_id']??$products[0]['product_id']);if(isset($ids[$id])){echo '<p><a class="admin-button" href="/admin/catalogue-image.php?product_id='.$id.'">Replace Product Image / restore</a></p>';echo '<section class="admin-panel"><p>Current status: <strong>'.($ids[$id]['active']?'Active':'Inactive').' · '.($ids[$id]['available']?'Availability ON':'Availability OFF').'</strong></p><form method="post">'.adminCsrfField().'<input type="hidden" name="product_id" value="'.$id.'"><input type="hidden" name="version" value="'.adminH($ids[$id]['version']).'"><input type="hidden" name="action" value="availability"><button class="admin-button" name="available" value="'.($ids[$id]['available']?'0':'1').'">'.($ids[$id]['available']?'DISABLE PRODUCT':'ENABLE PRODUCT').'</button></form><p>Inactive products remain hidden. Enabling availability does not approve routing.</p></section>';$d=$state['decisions'][(string)$id]??['decision'=>'PENDING','notes'=>'','version'=>0];echo '<section class="admin-panel"><h2>ID '.adminH($id).' — '.adminH($ids[$id]['name']).'</h2><form method="post">'.adminCsrfField().'<input type="hidden" name="product_id" value="'.$id.'"><input type="hidden" name="version" value="'.adminH($d['version']).'"><label>Decision<select name="decision">';foreach(\Kios\Infrastructure\CatalogueReviewStore::DECISIONS as $choice)echo '<option'.($choice===$d['decision']?' selected':'').'>'.adminH($choice).'</option>';echo '</select></label><label>Notes<textarea name="notes" maxlength="1000" rows="4">'.adminH($d['notes']).'</textarea></label><button class="admin-button">Save review decision</button></form></section>';}
echo '<h2>Review audit</h2><p>'.count($state['audit']).' recorded changes.</p>';foreach(array_reverse(array_slice($state['audit'],-50)) as $event)echo '<p>ID '.adminH($event['product_id']).' · '.adminH($event['after']['updated_utc']).' · '.adminH($event['before']['decision']).' → '.adminH($event['after']['decision']).'</p>';echo '</div>';adminEnd();
